+--
+--  SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
+--
+
+pragma Unevaluated_Use_Of_Old (Allow);
+
+pragma Assertion_Policy (Ghost          => Ignore,
+                         Pre            => Ignore,
+                         Post           => Ignore,
+                         Assert         => Ignore,
+                         Loop_Invariant => Ignore);
+
+with Heaps.Models;
+
+package body Heaps.Binomial with SPARK_Mode is
+
+   package KM renames Key_Multisets;
+
+   type Root_Table is array (Rank_Type) of Tree;
+
+   procedure Allocate (I : out Slot; K : Key_Type);
+   procedure Deallocate (I : Slot);
+
+   procedure Refresh (I : Slot) is
+   begin
+      Links (I).Size :=
+        1 + Size_Now (Links (I).Child) + Size_Now (Links (I).Sibling);
+      Sub (I) :=
+        KM.Add
+          (KM.Sum (Sub_Now (Links (I).Child),
+                  Sub_Now (Links (I).Sibling)),
+           Keys (I));
+   end Refresh;
+
+   procedure Refresh_Root_Suffix (I : Tree) is
+      Cur : Tree := I;
+   begin
+      while Cur /= 0 loop
+         Refresh (Cur);
+         Cur := Links (Cur).Prev;
+      end loop;
+   end Refresh_Root_Suffix;
+
+   procedure Link_Equal (A, B : Slot; R : out Slot) is
+      Top   : Slot;
+      Loser : Slot;
+      Kid   : Tree;
+   begin
+      if Keys (A) <= Keys (B) then
+         Top := A;
+         Loser := B;
+      else
+         Top := B;
+         Loser := A;
+      end if;
+
+      Kid := Links (Top).Child;
+
+      --  The loser becomes the first child of the winner.  The old first
+      --  child remains the next child and its parent does not change.
+
+      Links (Loser).Parent := Top;
+      Links (Loser).Prev := 0;
+      Links (Loser).Sibling := Kid;
+      if Kid /= 0 then
+         Links (Kid).Prev := Loser;
+      end if;
+      Links (Top).Child := Loser;
+
+      Refresh (Loser);
+      Links (Top).Rank := Links (Top).Rank + 1;
+      Refresh (Top);
+      R := Top;
+   end Link_Equal;
+
+   procedure Consolidate (T : in out Tree) is
+      Table : Root_Table := [others => 0];
+      Cur   : Tree;
+      Next  : Tree;
+      Carry : Slot;
+      Other : Slot;
+      Joined : Slot;
+      Head  : Tree := 0;
+      Root  : Tree;
+   begin
+      --  Take roots off the old list one at a time.  An isolated root's cache
+      --  no longer includes a root-list suffix, so refresh it before placing
+      --  it in the binary-counter table.
+
+      Cur := T;
+      T := 0;
+      while Cur /= 0 loop
+         Next := Links (Cur).Sibling;
+
+         if Next /= 0 then
+            Links (Next).Prev := 0;
+         end if;
+
+         Links (Cur).Sibling := 0;
+         Links (Cur).Prev := 0;
+         Links (Cur).Parent := 0;
+         Refresh (Cur);
+         Carry := Cur;
+
+         loop
+            Other := Table (Links (Carry).Rank);
+            exit when Other = 0;
+
+            Table (Links (Carry).Rank) := 0;
+            Link_Equal (Carry, Other, Joined);
+            Carry := Joined;
+         end loop;
+
+         Table (Links (Carry).Rank) := Carry;
+         Cur := Next;
+      end loop;
+
+      --  Rebuild the root list in increasing rank order.  Building it from
+      --  high to low makes the newly prepended root the smaller rank.
+
+      for R in reverse Rank_Type loop
+         Root := Table (R);
+         if Root /= 0 then
+            Links (Root).Parent := 0;
+            Links (Root).Prev := 0;
+            Links (Root).Sibling := Head;
+            if Head /= 0 then
+               Links (Head).Prev := Root;
+            end if;
+            Refresh (Root);
+            Head := Root;
+         end if;
+      end loop;
+
+      T := Head;
+   end Consolidate;
+
+   procedure Add_Root (T : in out Tree; R : in out Tree) is
+      Tail : Tree;
+   begin
+      if T = 0 then
+         Links (R).Parent := 0;
+         Links (R).Prev := 0;
+         Links (R).Sibling := 0;
+         Refresh (R);
+         T := R;
+      else
+         Tail := T;
+         while Links (Tail).Sibling /= 0 loop
+            Tail := Links (Tail).Sibling;
+         end loop;
+
+         Links (Tail).Sibling := R;
+         Links (R).Prev := Tail;
+         Links (R).Parent := 0;
+         Links (R).Sibling := 0;
+         Refresh_Root_Suffix (Tail);
+         Consolidate (T);
+      end if;
+      R := 0;
+   end Add_Root;
+
+   procedure Remove_Root (T : in out Tree; R : Slot) is
+      P : constant Tree := Links (R).Prev;
+      N : constant Tree := Links (R).Sibling;
+   begin
+      if P = 0 then
+         T := N;
+         if N /= 0 then
+            Links (N).Prev := 0;
+         end if;
+      else
+         Links (P).Sibling := N;
+         if N /= 0 then
+            Links (N).Prev := P;
+         end if;
+         Refresh_Root_Suffix (P);
+      end if;
+
+      Links (R).Sibling := 0;
+      Links (R).Prev := 0;
+      Links (R).Parent := 0;
+      Refresh (R);
+   end Remove_Root;
+
+   procedure Allocate (I : out Slot; K : Key_Type) is
+      Head : constant Slot := Free;
+      Next : constant Tree := Links (Head).Child;
+   begin
+      I := Head;
+      Free := Next;
+      Free_Count := Free_Count - 1;
+      Chain_Pos (Head) := 0;
+      Keys (Head) := K;
+      Links (Head) :=
+        (Child => 0, Sibling => 0, Parent => 0, Prev => 0,
+         Size => 1, Rank => 0);
+      Sub (Head) := KM.Add (KM.Empty_Multiset, K);
+   end Allocate;
+
+   procedure Deallocate (I : Slot) is
+   begin
+      Links (I) :=
+        (Child => Free, Sibling => 0, Parent => 0, Prev => 0,
+         Size => 0, Rank => 0);
+      Free_Count := Free_Count + 1;
+      Chain_Pos (I) := Free_Count;
+      Chain_At (Free_Count) := I;
+      Free := I;
+   end Deallocate;
+
+   -------------
+   -- Clear   --
+   -------------
+
+   procedure Clear is
+   begin
+      Chain_Pos := [for J in 1 .. Capacity => J];
+      Chain_At := [for J in 1 .. Capacity => J];
+      Sub := [for J in 1 .. Capacity => KM.Empty_Multiset];
+
+      for I in 1 .. Capacity loop
+         Links (I) :=
+           (Child => (if I = 1 then 0 else I - 1),
+            Sibling => 0, Parent => 0, Prev => 0,
+            Size => 0, Rank => 0);
+      end loop;
+
+      Free := Capacity;
+      Free_Count := Capacity;
+   end Clear;
+
+   -------------
+   -- Size_Of --
+   -------------
+
+   function Size_Of (T : Tree) return Extended_Index is
+     (Size_Now (T));
+
+   ----------------
+   -- Peek/Min_Of --
+   ----------------
+
+   function Peek_Min (T : Tree) return Key_Type is
+      Result : Key_Type := Keys (T);
+      Cur    : Tree := Links (T).Sibling;
+   begin
+      while Cur /= 0 loop
+         if Keys (Cur) < Result then
+            Result := Keys (Cur);
+         end if;
+         Cur := Links (Cur).Sibling;
+      end loop;
+      return Result;
+   end Peek_Min;
+
+   function Min_Of (T : Tree) return Key_Type is
+   begin
+      return Peek_Min (T);
+   end Min_Of;
+
+   ----------
+   -- Meld --
+   ----------
+
+   procedure Meld (T : in out Tree; U : in out Tree) is
+      R    : Tree;
+      Next : Tree;
+   begin
+      while U /= 0 loop
+         R := U;
+         Next := Links (R).Sibling;
+         U := Next;
+         if Next /= 0 then
+            Links (Next).Prev := 0;
+         end if;
+
+         Links (R).Sibling := 0;
+         Links (R).Prev := 0;
+         Links (R).Parent := 0;
+         Refresh (R);
+         Add_Root (T, R);
+      end loop;
+   end Meld;
+
+   ------------
+   -- Insert --
+   ------------
+
+   procedure Insert (T : in out Tree; K : Key_Type) is
+      R : Slot;
+   begin
+      Allocate (R, K);
+      Add_Root (T, R);
+   end Insert;
+
+   -----------------
+   -- Extract_Min --
+   -----------------
+
+   procedure Extract_Min (T : in out Tree; K : out Key_Type) is
+      Cur       : Tree := T;
+      Previous  : Tree := 0;
+      Gone      : Slot := T;
+      Gone_Prev : Tree := 0;
+      Child     : Tree;
+      Next      : Tree;
+      R         : Tree;
+   begin
+      --  Locate the minimum among the roots.  Every root is the minimum of
+      --  its own binomial tree, so this is the minimum of the whole forest.
+
+      while Cur /= 0 loop
+         if Keys (Cur) < Keys (Gone) then
+            Gone := Cur;
+            Gone_Prev := Previous;
+         end if;
+         Previous := Cur;
+         Cur := Links (Cur).Sibling;
+      end loop;
+
+      K := Keys (Gone);
+      Remove_Root (T, Gone);
+
+      --  Children are stored in decreasing rank order.  Each one becomes an
+      --  isolated root and is fed through the same binary-counter operation.
+
+      Child := Links (Gone).Child;
+      Links (Gone).Child := 0;
+      Refresh (Gone);
+
+      while Child /= 0 loop
+         Next := Links (Child).Sibling;
+         Links (Child).Sibling := 0;
+         Links (Child).Prev := 0;
+         Links (Child).Parent := 0;
+         Refresh (Child);
+
+         if Next /= 0 then
+            Links (Next).Prev := 0;
+         end if;
+
+         Links (Gone).Child := Next;
+         Refresh (Gone);
+         Add_Root (T, Child);
+         Child := Next;
+      end loop;
+
+      Links (Gone) :=
+        (Child => 0, Sibling => 0, Parent => 0, Prev => 0,
+         Size => 1, Rank => 0);
+      Sub (Gone) := KM.Add (KM.Empty_Multiset, K);
+      Deallocate (Gone);
+   end Extract_Min;
+
+end Heaps.Binomial;

